package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/Shopify/sarama"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb/types"
	"github.com/antonmedv/expr"
)

type EventMessage struct {
	TenantID  string            `json:"tenant_id"`
	Action    string            `json:"action"`
	Filter    string            `json:"filter"`
	Payload   map[string]string `json:"payload"`
}

type StreamProcessor struct {
	db    *dynamodb.Client
	table string
}

func NewStreamProcessor() (*StreamProcessor, error) {
	cfg, err := config.LoadDefaultConfig(context.TODO(),
		config.WithRegion(os.Getenv("AWS_REGION")),
	)
	if err != nil {
		return nil, err
	}
	return &StreamProcessor{
		db:    dynamodb.NewFromConfig(cfg),
		table: os.Getenv("DYNAMODB_TABLE"),
	}, nil
}

// evaluateFilter uses expr library to evaluate user-provided filter expressions
// against the event payload for dynamic routing decisions
func (sp *StreamProcessor) evaluateFilter(msg EventMessage) (bool, error) {
	if msg.Filter == "" {
		return true, nil
	}

	// Build environment from payload fields
	env := make(map[string]interface{})
	for k, v := range msg.Payload {
		env[k] = v
	}
	env["tenant"] = msg.TenantID
	env["action"] = msg.Action

	// VULNERABILITY: User-controlled expression is compiled and executed
	// The expr library allows function calls and property access
	// An attacker can craft expressions that access internal state
	program, err := expr.Compile(msg.Filter)
	if err != nil {
		return false, fmt.Errorf("filter compilation failed: %w", err)
	}

	result, err := expr.Run(program, env)
	if err != nil {
		return false, fmt.Errorf("filter execution failed: %w", err)
	}

	if b, ok := result.(bool); ok {
		return b, nil
	}
	return false, fmt.Errorf("filter did not return boolean")
}

func (sp *StreamProcessor) writeEvent(ctx context.Context, msg EventMessage) error {
	item := map[string]types.AttributeValue{
		"PK":        &types.AttributeValueMemberS{Value: fmt.Sprintf("TENANT#%s", msg.TenantID)},
		"SK":        &types.AttributeValueMemberS{Value: fmt.Sprintf("EVENT#%s", msg.Action)},
		"tenant_id": &types.AttributeValueMemberS{Value: msg.TenantID},
		"action":    &types.AttributeValueMemberS{Value: msg.Action},
	}

	for k, v := range msg.Payload {
		if !strings.ContainsAny(k, "#.") {
			item[k] = &types.AttributeValueMemberS{Value: v}
		}
	}

	_, err := sp.db.PutItem(ctx, &dynamodb.PutItemInput{
		TableName: aws.String(sp.table),
		Item:      item,
	})
	return err
}

func (sp *StreamProcessor) HandleMessage(ctx context.Context, raw []byte) error {
	var msg EventMessage
	if err := json.Unmarshal(raw, &msg); err != nil {
		return fmt.Errorf("unmarshal failed: %w", err)
	}

	if msg.TenantID == "" || msg.Action == "" {
		return fmt.Errorf("missing required fields")
	}

	pass, err := sp.evaluateFilter(msg)
	if err != nil {
		log.Printf("filter error for tenant %s: %v", msg.TenantID, err)
		return err
	}

	if pass {
		return sp.writeEvent(ctx, msg)
	}
	return nil
}

func main() {
	sp, err := NewStreamProcessor()
	if err != nil {
		log.Fatal(err)
	}

	consumer, err := sarama.NewConsumer(strings.Split(os.Getenv("KAFKA_BROKERS"), ","), nil)
	if err != nil {
		log.Fatal(err)
	}
	defer consumer.Close()

	partConsumer, err := consumer.ConsumePartition(os.Getenv("KAFKA_TOPIC"), 0, sarama.OffsetNewest)
	if err != nil {
		log.Fatal(err)
	}
	defer partConsumer.Close()

	ctx := context.Background()
	for msg := range partConsumer.Messages() {
		if err := sp.HandleMessage(ctx, msg.Value); err != nil {
			log.Printf("error processing message at offset %d: %v", msg.Offset, err)
		}
	}
}
